from __future__ import annotations
import dataclasses, hashlib, importlib.metadata, json, math, os, platform, subprocess, sys
from pathlib import Path
from statistics import fmean

from embodiment.physics3d.alternative_bodies import CRAWLER_SPEC, CrawlerPhysics
from embodiment.physics3d.mechanics import GROUND_MATERIAL
from embodiment.physics3d.scene import PhysicsScene
from lab.physics3d.settling import settle_passive_body

G = 9.81
DT = 1.0 / 240.0
RUN_ID = os.environ["SYMBIONT_RUN_ID"]
WORK = Path(os.environ["SYMBIONT_RUN_WORK"])

def plain(value):
    if dataclasses.is_dataclass(value):
        return {k: plain(v) for k, v in dataclasses.asdict(value).items()}
    if isinstance(value, dict):
        return {str(k): plain(v) for k, v in value.items()}
    if isinstance(value, (tuple, list)):
        return [plain(v) for v in value]
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    return repr(value)

def vec(values):
    return [float(v) for v in values]

def norm(values):
    return math.sqrt(sum(float(v) ** 2 for v in values))

def model_record(scene, body):
    import mujoco
    m = scene.model
    name = lambda typ, i: mujoco.mj_id2name(m, typ, i) or f"unnamed-{i}"
    joints = []
    for i in range(int(m.njnt)):
        d = int(m.jnt_dofadr[i])
        joints.append({"name": name(mujoco.mjtObj.mjOBJ_JOINT, i), "type": int(m.jnt_type[i]), "limited": bool(m.jnt_limited[i]), "range": vec(m.jnt_range[i]), "damping": float(m.dof_damping[d]) if d < m.nv else None, "frictionloss": float(m.dof_frictionloss[d]) if d < m.nv else None, "armature": float(m.dof_armature[d]) if d < m.nv else None, "stiffness": float(m.jnt_stiffness[i])})
    geoms = []
    for i in range(int(m.ngeom)):
        geoms.append({"name": name(mujoco.mjtObj.mjOBJ_GEOM, i), "body_id": int(m.geom_bodyid[i]), "type": int(m.geom_type[i]), "size": vec(m.geom_size[i]), "friction": vec(m.geom_friction[i]), "condim": int(m.geom_condim[i]), "solref": vec(m.geom_solref[i]), "solimp": vec(m.geom_solimp[i]), "margin": float(m.geom_margin[i])})
    bodies = []
    for i in range(int(m.nbody)):
        bodies.append({"name": name(mujoco.mjtObj.mjOBJ_BODY, i), "mass_kg": float(m.body_mass[i]), "inertia": vec(m.body_inertia[i]), "ipos": vec(m.body_ipos[i])})
    return {"counts": {"nbody": int(m.nbody), "njnt": int(m.njnt), "ngeom": int(m.ngeom), "nq": int(m.nq), "nv": int(m.nv)}, "options": {"timestep_s": float(m.opt.timestep), "gravity_m_s2": vec(m.opt.gravity), "solver": int(m.opt.solver), "integrator": int(m.opt.integrator), "iterations": int(m.opt.iterations), "tolerance": float(m.opt.tolerance)}, "bodies": bodies, "joints": joints, "geoms": geoms, "body_mass_distribution": {"total_mass_kg": float(body.mass_distribution()[0]), "center_of_mass_m": vec(body.mass_distribution()[1])}}

def capture(scene, body, phase, tick):
    pos, quat = body.base_pose()
    linear, angular = body.base_velocity()
    joints = body.joint_states()
    total_mass, com = body.mass_distribution()
    contacts = [c for c in body.contact_details() if int(c["other_body_id"]) == 0]
    rec = {"phase": phase, "tick": tick, "time_s": float(scene.data.time), "base_position_m": vec(pos), "base_quaternion_xyzw": vec(quat), "base_linear_velocity_m_s": vec(linear), "base_angular_velocity_rad_s": vec(angular), "joint_position_rad": {s.name: float(joints[i][0]) for i, s in enumerate(CRAWLER_SPEC.joint_specs)}, "joint_velocity_rad_s": {s.name: float(joints[i][1]) for i, s in enumerate(CRAWLER_SPEC.joint_specs)}, "center_of_mass_m": vec(com), "body_mass_kg": float(total_mass), "ground_contact_count": len(contacts), "ground_normal_reaction_n": sum(float(c["normal_force"]) for c in contacts), "ground_penetration_max_m": max((max(0.0, -float(c["distance"])) for c in contacts), default=0.0), "ground_contacts": [{"link_index": int(c["link_index"]), "link_name": c["link_name"], "position_m": vec(c["position"]), "normal": vec(c["normal"]), "normal_force_n": float(c["normal_force"]), "distance_m": float(c["distance"])} for c in contacts]}
    def check(x):
        if isinstance(x, float): return math.isfinite(x)
        if isinstance(x, dict): return all(check(v) for v in x.values())
        if isinstance(x, list): return all(check(v) for v in x)
        return True
    rec["finite"] = check({k:v for k,v in rec.items() if k != "finite"})
    return rec

def run_rep(rep):
    scene = PhysicsScene(timestep=DT, gravity=(0.0, 0.0, -G))
    scene.add_ground(GROUND_MATERIAL)
    body = CrawlerPhysics(scene)
    trace = []
    original_step = scene.step
    phase = "settling"
    tick = 0
    trace.append(capture(scene, body, "initial", tick))
    def measured_step():
        nonlocal tick
        original_step()
        tick += 1
        trace.append(capture(scene, body, phase, tick))
    scene.step = measured_step
    effective = model_record(scene, body)
    settle = settle_passive_body(scene, body)
    post_summary = None
    if settle.converged:
        phase = "post_settle"
        body.apply_effectors({})
        post = [x for x in trace if x["phase"] == "post_settle"]
        for _ in range(480):
            body.prepare_physics_substep()
            scene.step()
        post = [x for x in trace if x["phase"] == "post_settle"]
        forces = [x["ground_normal_reaction_n"] for x in post]
        pen = [x["ground_penetration_max_m"] for x in post]
        contacts = [x["ground_contact_count"] for x in post]
        start, end = post[0], post[-1]
        post_summary = {"steps": len(post), "base_drift_m": math.dist(start["base_position_m"], end["base_position_m"]), "com_height_start_m": start["center_of_mass_m"][2], "com_height_end_m": end["center_of_mass_m"][2], "com_drift_m": abs(end["center_of_mass_m"][2]-start["center_of_mass_m"][2]), "mean_ground_reaction_n": fmean(forces), "max_ground_reaction_n": max(forces), "expected_weight_n": effective["body_mass_distribution"]["total_mass_kg"]*G, "reaction_to_weight_ratio": fmean(forces)/(effective["body_mass_distribution"]["total_mass_kg"]*G), "max_ground_penetration_m": max(pen), "mean_ground_penetration_m": fmean(pen), "mean_ground_contact_points": fmean(contacts), "max_ground_contact_points": max(contacts), "max_base_linear_speed_m_s": max(norm(x["base_linear_velocity_m_s"]) for x in post), "max_base_angular_speed_rad_s": max(norm(x["base_angular_velocity_rad_s"]) for x in post), "max_joint_speed_rad_s": max((abs(v) for x in post for v in x["joint_velocity_rad_s"].values()), default=0.0)}
    finite = all(x["finite"] for x in trace)
    return {"replicate": rep, "effective_model": effective, "settling": settle.as_dict(), "post_settle_summary": post_summary, "finite_all_steps": finite, "disposition": "reportable" if finite and settle.converged and post_summary is not None else "not_evaluable", "trace": trace}

source_commit = subprocess.check_output(["git", "rev-parse", "HEAD"], text=True).strip()
lock_hash = hashlib.sha256(Path("uv.lock").read_bytes()).hexdigest()
runner_config_hash = hashlib.sha256(os.environ["SYMBIONT_EFFECTIVE_CONFIG"].encode()).hexdigest()
report = {"protocol": "crawler-passive-characterization-v1", "run_id": RUN_ID, "source_commit": source_commit, "seed": None, "launcher_seed_bookkeeping": int(os.environ["SYMBIONT_SEED"]), "no_stochastic_input": True, "runner_effective_config_sha256": runner_config_hash, "dependency_versions": {"python": sys.version, "platform": platform.platform(), "mujoco": importlib.metadata.version("mujoco"), "numpy": importlib.metadata.version("numpy"), "uv_lock_sha256": lock_hash}, "declared_inputs": {"crawler_spec": plain(CRAWLER_SPEC), "ground_material": plain(GROUND_MATERIAL)}, "replicates": [run_rep(1), run_rep(2)]}
report["disposition"] = "reportable" if all(r["disposition"] == "reportable" for r in report["replicates"]) else "not_evaluable"
report_path = WORK / "crawler-passive-characterization.json"
raw = json.dumps(report, sort_keys=True, indent=2, allow_nan=False).encode()
report_path.write_bytes(raw)
manifest = {"protocol": report["protocol"], "run_id": RUN_ID, "source_commit": source_commit, "artifacts": {report_path.name: "sha256:" + hashlib.sha256(raw).hexdigest()}, "runner_effective_config_sha256": runner_config_hash, "replicate_dispositions": [r["disposition"] for r in report["replicates"]], "overall_disposition": report["disposition"]}
manifest_path = WORK / "artifact-manifest.json"
manifest_path.write_text(json.dumps(manifest, sort_keys=True, indent=2) + "\n")
print(json.dumps({"run_id": RUN_ID, "source_commit": source_commit, "disposition": report["disposition"], "replicates": [{"settling": r["settling"], "post_settle_summary": r["post_settle_summary"], "trace_records": len(r["trace"]), "finite_all_steps": r["finite_all_steps"], "disposition": r["disposition"]} for r in report["replicates"]], "report_sha256": hashlib.sha256(raw).hexdigest(), "runner_effective_config_sha256": runner_config_hash}, sort_keys=True))
